        $sent++;

        return Http::response('', 200);
    });

    $endpoint = WebhookTestHelpers::endpoint(['is_active' => false, 'disabled_reason' => 'manual', 'disabled_at' => now()]);
    $delivery = WebhookTestHelpers::delivery($endpoint, [
