    WebhookTestHelpers::deliver($delivery);

    expect($sent)->toBe(0)
        ->and($delivery->refresh()->status)->toBe('pending');
});

it('redeliver then deactivate-before-save still must not POST', function (): void {
    $sent = 0;
    Http::fake(function () use (&$sent) {
        $sent++;

        return Http::response('', 200);
