<?php

declare(strict_types=1);

use Illuminate\Foundation\Testing\RefreshDatabase;
use Vaulter\Actions\Webhooks\UpdateWebhookEndpointAction;
use Vaulter\Data\Webhooks\UpdateWebhookEndpointInput;
use Vaulter\Models\Webhooks\WebhookEndpoint;
use Vaulter\Tests\TestCase;
use Vaulter\Tests\Webhooks\WebhookTestHelpers;

uses(TestCase::class, RefreshDatabase::class);

it('kills open deliveries when a stale active instance is updated to inactive', function (): void {
    $endpoint = WebhookTestHelpers::endpoint();
    $open = WebhookTestHelpers::delivery($endpoint);
    $stale = WebhookEndpoint::query()->findOrFail($endpoint->getKey());

    // Another request already switched it off and killed the delivery.
    app(UpdateWebhookEndpointAction::class)->execute(
        $endpoint,
        new UpdateWebhookEndpointInput(url: null, events: null, isActive: false),
    );
    expect($open->refresh()->status)->toBe('dead');

    // The owner turns it back on; the dead row stays dead (redelivery is explicit).
    app(UpdateWebhookEndpointAction::class)->execute(
        $endpoint->fresh(),
        new UpdateWebhookEndpointInput(url: null, events: null, isActive: true),
    );

    // A new delivery is waiting.
    $again = WebhookTestHelpers::delivery($endpoint->fresh());

    // The stale instance still believes the endpoint is active, then sets is_active=false.
    expect($stale->is_active)->toBeTrue();
    app(UpdateWebhookEndpointAction::class)->execute(
        $stale,
        new UpdateWebhookEndpointInput(url: null, events: null, isActive: false),
    );

    expect($endpoint->fresh()->is_active)->toBeFalse()
        ->and($endpoint->fresh()->disabled_reason)->toBe('manual')
        ->and($again->refresh()->status)->toBe('dead');
});
EOF
