uses(TestCase::class, RefreshDatabase::class);

it('a stale is_active=false model leaves the new delivery pending, and the job POSTs it', function (): void {
    $sent = 0;
    Http::fake(function () use (&$sent) {
        $sent++;

        return Http::response('', 200);
    });

    $endpoint = WebhookTestHelpers::endpoint(['is_active' => false, 'disabled_reason' => 'manual', 'disabled_at' => now()]);
    $loadedWhileOff = WebhookEndpoint::query()->findOrFail($endpoint->getKey());

    app(UpdateWebhookEndpointAction::class)->execute(
        $endpoint->fresh(),
        new UpdateWebhookEndpointInput(url: null, events: null, isActive: true),
    );
    $open = WebhookTestHelpers::delivery($endpoint->fresh(), [
        'payload' => ['id' => 'evt-stale', 'type' => 'folder.created'],
    ]);

    app(UpdateWebhookEndpointAction::class)->execute(
        $loadedWhileOff,
        new UpdateWebhookEndpointInput(url: 'https://hooks.test/receive', events: null, isActive: false),
    );

    expect($endpoint->fresh()->is_active)->toBeFalse()
        ->and($open->refresh()->status)->toBe('pending');

    WebhookTestHelpers::deliver($open->fresh());

    expect($sent)->toBe(0);
});
